const express = require('express');
const helmet = require('helmet');       // Sets secure HTTP headers
const rateLimit = require('express-rate-limit'); // Prevents abuse
const cors = require('cors');           // Controls cross-origin access

const app = express();

// --- Security Middleware ---

// Set various HTTP security headers automatically
app.use(helmet());

// Configure CORS – restrict to known origins in production
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS
    ? process.env.ALLOWED_ORIGINS.split(',')
    : 'http://localhost:3000',
  methods: ['GET'],
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// Rate limiting – prevent brute-force / DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                  // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// Body parsing with size limits (for future POST/PUT routes)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// --- Disable fingerprinting ---
app.disable('x-powered-by'); // Also handled by helmet, but explicit is good

// --- Routes ---

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

