  // Input validation example: validate query params if pagination is added
  const page = parseInt(req.query.page, 10);
  const limit = parseInt(req.query.limit, 10);

  if (req.query.page && (isNaN(page) || page < 1)) {
    return res.status(400).json({ error: 'Invalid "page" parameter. Must be a positive integer.' });
  }
  if (req.query.limit && (isNaN(limit) || limit < 1 || limit > 100)) {
    return res.status(400).json({ error: 'Invalid "limit" parameter. Must be between 1 and 100.' });
  }

  // Never expose internal/sensitive fields – whitelist the response shape
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json({ data: users, meta: { page: page || 1, limit: limit || 10 } });
});

// --- 404 Handler ---
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found' });
});

// --- Global Error Handler ---
// Must have 4 parameters for Express to recognize it as an error handler
app.use((err, req, res, next) => {
  // Log full error internally (use a real logger like winston/pino in production)
  console.error(`[${new Date().toISOString()}] Unhandled error:`, err.message);

  // Never leak stack traces or internal details to the client
  const statusCode = err.statusCode || 500;
  const message =
    process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message;

  res.status(statusCode).json({ error: message });
});

